int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd)
{
    if (cmd->msg_len > DVB_MAX_DISEQC_MSG_SIZE)
        return -EINVAL;

    memcpy(fe->diseqc_buf, cmd->msg, cmd->msg_len);
    return fe->ops.send_cmd(fe, fe->diseqc_buf, cmd->msg_len);
}

